const http = require('node:http');
const fs = require('node:fs/promises');
const path = require('node:path');

const ENDPOINT = 'http://127.0.0.1:54252/status';

function get(url) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      let body = '';
      res.setEncoding('utf8');
      res.on('data', (chunk) => { body += chunk; });
      res.on('end', () => resolve({ statusCode: res.statusCode, body }));
    }).on('error', reject);
  });
}

async function main() {
  const { statusCode, body } = await get(ENDPOINT);
  const data = JSON.parse(body);

  if (statusCode !== 200 || data.status !== 200) {
    throw new Error(`Unexpected status: HTTP ${statusCode}, body ${body}`);
  }

  const outDir = path.join(__dirname, 'results');
  await fs.mkdir(outDir, { recursive: true });
  await fs.writeFile(
    path.join(outDir, 'status.json'),
    JSON.stringify({ status: data.status }, null, 2) + '\n',
    'utf8'
  );

  console.log('Wrote results/status.json with status=200');
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});

